      const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X + (int64_t)c * HW);
      float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y + (int64_t)c * HW);
      const int64_t sN4 = sN >> 2;
      for (int n = 0; n < N; ++n) {
