        float4* __restrict__ yrow = Y4 + (int64_t)n * sN4;
        for (int p = tid; p < HW4; p += blockDim.x) {
          float4 v = __ldg(xrow + p);
          v.x = v.x * scale + shift;
          v.y = v.y * scale + shift;
          v.z = v.z * scale + shift;
          v.w = v.w * scale + shift;
